--
-- Name: vw_absent_appointment; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_absent_appointment AS
 SELECT row_number() OVER (ORDER BY appt_date) AS id,
    appt_date AS date,
    sum(
        CASE
            WHEN ((reason_discard_appointment)::text = 'ไม่รับ'::text) THEN 1
            ELSE 0
        END) AS rejected,
    sum(
        CASE
            WHEN ((reason_discard_appointment)::text = 'ติดต่อไม่ได้'::text) THEN 1
            ELSE 0
        END) AS unreachable,
    sum(
        CASE
            WHEN ((reason_discard_appointment)::text = 'ติดธุระ/ไม่สะดวก'::text) THEN 1
            ELSE 0
        END) AS busy,
    sum(
        CASE
            WHEN ((reason_discard_appointment)::text = 'ตรวจที่โรงพยาบาลอื่น'::text) THEN 1
            ELSE 0
        END) AS other_hospital,
    sum(
        CASE
            WHEN ((reason_discard_appointment)::text = 'ลืมนัด'::text) THEN 1
            ELSE 0
        END) AS forgot,
    sum(
        CASE
            WHEN ((reason_discard_appointment)::text = 'สิทธิ์ไม่ส่งตัว'::text) THEN 1
            ELSE 0
        END) AS no_referral,
    sum(
        CASE
            WHEN ((reason_discard_appointment)::text = 'ไม่สบาย'::text) THEN 1
            ELSE 0
        END) AS sick,
    sum(
        CASE
            WHEN ((reason_discard_appointment)::text = 'เสียชีวิต'::text) THEN 1
            ELSE 0
        END) AS deceased,
    sum(
        CASE
            WHEN ((reason_discard_appointment IS NULL) OR ((reason_discard_appointment)::text = ''::text) OR ((reason_discard_appointment)::text = 'อื่นๆ'::text)) THEN 1
            ELSE 0
        END) AS other,
    count(*) AS all_absent
   FROM ( SELECT (appointment.appointment_datetime AT TIME ZONE 'Asia/Bangkok'::text) AS appt_datetime,
            ((appointment.appointment_datetime AT TIME ZONE 'Asia/Bangkok'::text))::date AS appt_date,
            appointment.reason_discard_appointment
           FROM public.appointment
          WHERE (((appointment.appointment_status)::text = 'ไม่มาตามนัด'::text) AND (appointment.appointment_datetime IS NOT NULL))) sub
  GROUP BY appt_date
  ORDER BY appt_date;


--
-- Name: vw_appointment_day_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_appointment_day_summary AS
 SELECT d.appointment_datetime AS appointment_date,
    COALESCE(count(a.id), (0)::bigint) AS appointment_count,
        CASE
            WHEN (h.date IS NOT NULL) THEN true
            ELSE false
        END AS is_holiday,
    COALESCE(sum(
        CASE
            WHEN ((ts.time_period)::text = 'morning'::text) THEN 1
            ELSE 0
        END), (0)::bigint) AS morning_appointment_count,
    COALESCE(sum(
        CASE
            WHEN ((ts.time_period)::text = 'afternoon'::text) THEN 1
            ELSE 0
        END), (0)::bigint) AS afternoon_appointment_count,
    COALESCE(sum(
        CASE
            WHEN ((ts.time_period)::text = 'evening'::text) THEN 1
            ELSE 0
        END), (0)::bigint) AS evening_appointment_count
   FROM (((( SELECT DISTINCT date(appointment.appointment_datetime) AS appointment_datetime
           FROM public.appointment
        UNION
         SELECT holiday.date
           FROM public.holiday) d
     LEFT JOIN public.appointment a ON ((date(a.appointment_datetime) = d.appointment_datetime)))
     LEFT JOIN public.time_slot ts ON ((a.time_slot = ts.id)))
     LEFT JOIN public.holiday h ON ((d.appointment_datetime = h.date)))
  WHERE ((a.appointment_status)::text <> 'ยกเลิกนัด'::text)
  GROUP BY d.appointment_datetime, h.date
  ORDER BY d.appointment_datetime DESC;


--
-- Name: vw_appointment_slot_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_appointment_slot_summary AS
 SELECT date(appointment_datetime) AS appointment_date,
    time_slot,
    count(*) AS appointment_count
   FROM public.appointment
  WHERE ((appointment_status)::text <> 'ยกเลิกนัด'::text)
  GROUP BY (date(appointment_datetime)), time_slot
  ORDER BY (date(appointment_datetime)) DESC, time_slot;


--
-- Name: vw_nurse_work_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_nurse_work_summary AS
 SELECT row_number() OVER () AS id,
    to_char(a.appointment_datetime, 'DD'::text) AS day,
    to_char(a.appointment_datetime, 'MM'::text) AS month,
    to_char(a.appointment_datetime, 'YYYY'::text) AS year,
    ts.slot,
    ts.time_period,
    count(*) FILTER (WHERE ((bx.label)::text = 'Ultrasound guided'::text)) AS us,
    count(*) FILTER (WHERE ((bx.label)::text = 'Stereotactic guided'::text)) AS st,
    count(DISTINCT a.id) AS appointment_count
   FROM ((((public.nurse_work nw
     JOIN public.appointment a ON ((nw.appointment = a.id)))
     JOIN public.time_slot ts ON ((a.time_slot = ts.id)))
     JOIN public.special_procedure_plans spp ON ((nw.id = spp.nurse_work)))
     LEFT JOIN public.bx_options bx ON ((spp.technique = bx.id)))
  WHERE ((a.appointment_datetime IS NOT NULL) AND ((a.appointment_status)::text <> 'ยกเลิกนัด'::text) AND ((a.appointment_status)::text <> 'ไม่มาตามนัด'::text))
  GROUP BY (to_char(a.appointment_datetime, 'DD'::text)), (to_char(a.appointment_datetime, 'MM'::text)), (to_char(a.appointment_datetime, 'YYYY'::text)), ts.slot, ts.time_period
  ORDER BY (to_char(a.appointment_datetime, 'YYYY'::text)), (to_char(a.appointment_datetime, 'MM'::text)), (to_char(a.appointment_datetime, 'DD'::text)), ts.time_period, ts.slot;


--
-- Name: vw_report_front_visited; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_report_front_visited AS
 SELECT row_number() OVER () AS id,
    (((a.appointment_datetime AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Asia/Bangkok'::text))::date AS date,
    count(
        CASE
            WHEN ((ts.time_period)::text = 'morning'::text) THEN 1
            ELSE NULL::integer
        END) AS morning_all,
    count(
        CASE
            WHEN (((ts.time_period)::text = 'morning'::text) AND ((a.appointment_status)::text <> ALL (ARRAY[('ไม่มาตามนัด'::character varying)::text, ('ยังไม่ถึงเวลานัด/ยังไม่มา'::character varying)::text]))) THEN 1
            ELSE NULL::integer
        END) AS morning_visited,
    count(
        CASE
            WHEN ((ts.time_period)::text = 'afternoon'::text) THEN 1
            ELSE NULL::integer
        END) AS afternoon_all,
    count(
        CASE
            WHEN (((ts.time_period)::text = 'afternoon'::text) AND ((a.appointment_status)::text <> ALL (ARRAY[('ไม่มาตามนัด'::character varying)::text, ('ยังไม่ถึงเวลานัด/ยังไม่มา'::character varying)::text]))) THEN 1
            ELSE NULL::integer
        END) AS afternoon_visited,
    count(
        CASE
            WHEN ((ts.time_period)::text = 'evening'::text) THEN 1
            ELSE NULL::integer
        END) AS evening_all,
    count(
        CASE
            WHEN (((ts.time_period)::text = 'evening'::text) AND ((a.appointment_status)::text <> ALL (ARRAY[('ไม่มาตามนัด'::character varying)::text, ('ยังไม่ถึงเวลานัด/ยังไม่มา'::character varying)::text]))) THEN 1
            ELSE NULL::integer
        END) AS evening_visited,
    count(a.id) AS total_appointment,
    count(
        CASE
            WHEN ((a.appointment_status)::text <> ALL (ARRAY[('ไม่มาตามนัด'::character varying)::text, ('ยังไม่ถึงเวลานัด/ยังไม่มา'::character varying)::text])) THEN 1
            ELSE NULL::integer
        END) AS total_visited
   FROM (public.appointment a
     LEFT JOIN public.time_slot ts ON ((a.time_slot = ts.id)))
  WHERE (((a.appointment_status)::text <> 'ยกเลิกนัด'::text) AND (a.appointment_datetime IS NOT NULL))
  GROUP BY ((((a.appointment_datetime AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Asia/Bangkok'::text))::date)
  ORDER BY ((((a.appointment_datetime AT TIME ZONE 'UTC'::text) AT TIME ZONE 'Asia/Bangkok'::text))::date) DESC;


--
-- Name: vw_request_appointment; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_request_appointment AS
 WITH appt_with_local_hour AS (
         SELECT appointment.appointment_channels,
            appointment.is_insert_queue,
            EXTRACT(hour FROM appointment.receive_date) AS creation_hour,
            (date_trunc('day'::text, appointment.receive_date))::date AS creation_date
           FROM public.appointment
          WHERE ((appointment.is_insert_queue IS NOT TRUE) AND (appointment.receive_date IS NOT NULL) AND (appointment.appointment_datetime IS NOT NULL))
        )
 SELECT creation_date AS date,
    count(
        CASE
            WHEN ((appointment_channels)::text = 'Telemed'::text) THEN 1
            ELSE NULL::integer
        END) AS telemed_request,
    count(
        CASE
            WHEN (((appointment_channels)::text <> 'Telemed'::text) AND (creation_hour >= (8)::numeric) AND (creation_hour < (16)::numeric)) THEN 1
            ELSE NULL::integer
        END) AS morning_request,
    count(
        CASE
            WHEN (((appointment_channels)::text <> 'Telemed'::text) AND (creation_hour >= (16)::numeric) AND (creation_hour < (20)::numeric)) THEN 1
            ELSE NULL::integer
        END) AS afternoon_request,
    count(*) AS total_appointment
   FROM appt_with_local_hour
  GROUP BY creation_date
  ORDER BY creation_date;


--
-- Name: vw_summary_appointment; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_summary_appointment AS
 WITH appt_local AS (
         SELECT ((appointment.appointment_datetime AT TIME ZONE 'Asia/Bangkok'::text))::date AS appointment_date,
            (appointment.appointment_datetime AT TIME ZONE 'Asia/Bangkok'::text) AS appointment_datetime,
            appointment.appointment_status,
            appointment.is_change_time_slot,
            appointment.is_insert_queue
           FROM public.appointment
          WHERE (appointment.appointment_datetime IS NOT NULL)
        )
 SELECT appointment_date AS date,
    (((10 * 12) + (8 * 12)) + 33) AS scheduled_count,
    count(appointment_datetime) AS confirmed_count,
    count(*) FILTER (WHERE ((appointment_status)::text = 'ไม่มาตามนัด'::text)) AS absented_count,
    count(*) FILTER (WHERE ((is_change_time_slot = true) AND ((appointment_status)::text = 'ส่งตรวจ'::text))) AS rescheduled_count,
    count(*) FILTER (WHERE ((appointment_status)::text = 'ยกเลิกนัด'::text)) AS cancelled_count,
    count(*) FILTER (WHERE ((is_insert_queue = true) AND ((appointment_status)::text = 'ส่งตรวจ'::text))) AS added_count,
    ((count(appointment_datetime) - ((count(*) FILTER (WHERE ((appointment_status)::text = 'ไม่มาตามนัด'::text)) + count(*) FILTER (WHERE ((is_change_time_slot = true) AND ((appointment_status)::text = 'ส่งตรวจ'::text)))) + count(*) FILTER (WHERE ((appointment_status)::text = 'ยกเลิกนัด'::text)))) + count(*) FILTER (WHERE ((is_insert_queue = true) AND ((appointment_status)::text = 'ส่งตรวจ'::text)))) AS summary_count
   FROM appt_local
  GROUP BY appointment_date
  ORDER BY appointment_date;


--
-- Name: worklist; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.worklist (
    id integer NOT NULL,
    user_created uuid,
    date_created timestamp with time zone,
    user_updated uuid,
    date_updated timestamp with time zone,
    appointment bigint,
    patient_info integer,
    care_type character varying(255) DEFAULT NULL::character varying,
    outpatient json,
    an character varying(255) DEFAULT NULL::character varying,
    room character varying(255) DEFAULT NULL::character varying,
    building character varying(255) DEFAULT NULL::character varying,
    issue_an_invoice boolean,
    queue integer,
    end_time timestamp without time zone,
    start_time timestamp without time zone
);


